#!/bin/sh
# TARGET (busybox sh): run a demo with the assets generated by gen_assets.sh. Details: README.md
# usage: [ENV=value ...] ./run_demo.sh <cockpit|dashboard> <assets-dir> [demo args]
DEMO=$1; A=$2; [ $# -ge 2 ] && shift 2
case $DEMO in cockpit|dashboard) ;; *) echo "usage: $0 <cockpit|dashboard> <assets-dir> [args]"; exit 1 ;; esac
[ -d "$A/videos" ] || { echo "'$A/videos' not found: pass the directory generated by gen_assets.sh"; exit 1; }
A=$(cd "$A" && pwd)
export XDG_RUNTIME_DIR=/tmp/xdg WAYLAND_DISPLAY=wayland-1
mkdir -p $XDG_RUNTIME_DIR
# restart Weston: start_weston kiosk|ivi
start_weston() {
	# systemd images run Weston as a service (user weston, VT7, socket-activated); stop it, else it keeps
	# the DRM master and respawns. Restore later with: systemctl start weston.socket weston.service
	command -v systemctl >/dev/null && systemctl stop weston.service weston.socket 2>/dev/null
	for p in $(pidof weston); do kill -9 $p 2>/dev/null; done; sleep 2
	rm -f $XDG_RUNTIME_DIR/wayland-1 $XDG_RUNTIME_DIR/wayland-1.lock
	# --tty was removed in Weston 11+ (libseat); only older Weston needs it
	TTY=--tty=1; [ "$(weston --version 2>/dev/null | sed 's/[^0-9]*\([0-9]*\).*/\1/')" -ge 11 ] 2>/dev/null && TTY=
	weston $TTY --backend=drm-backend.so --config=/etc/xdg/weston/weston-$1.ini --shell=$1-shell.so --use-pixman >/tmp/weston.log 2>&1 &
	n=0; while [ ! -S $XDG_RUNTIME_DIR/wayland-1 ] && [ $n -lt 20 ]; do sleep 1; n=$((n+1)); done; sleep 2
	[ -S $XDG_RUNTIME_DIR/wayland-1 ] || { echo "Weston failed to start, see /tmp/weston.log"; exit 1; }
}
MODE=$(cat /sys/class/drm/card*-*/modes 2>/dev/null | head -n 1)
[ -n "$MODE" ] || { echo "cannot read panel mode"; exit 1; }

if [ "$DEMO" = cockpit ]; then
	SH=${WESTON_SHELL:-kiosk}
	case $SH in kiosk|ivi) ;; *) echo "WESTON_SHELL must be kiosk or ivi"; exit 1 ;; esac
	C=cockpit_$MODE
	[ -f "$A/videos/$C.h264" ] || { echo "missing $A/videos/$C.h264 (generate with gen_assets.sh --panel $MODE)"; exit 1; }
	# defaults: 16 bpp alpha UI, unsynced video; override via env
	F=argb4444; SY=false; UF=30
	LOG=/tmp/demo_gst.log; : >$LOG
	start_weston $SH
	# kiosk: video first (takes the overlay plane, then moves to primary), then the Qt UI.
	# ivi: video = surface 1000 (layer order 0, primary), Qt UI = surface 2000 (order 1, overlay).
	[ $SH = ivi ] && export GST_WAYLANDSINK_IVI_SURFACE_ID=1000
	gst-launch-1.0 -v filesrc location=$A/videos/$C.h264 ! h264parse ! v4l2slh264dec ! \
		fpsdisplaysink video-sink=waylandsink text-overlay=false sync=${SYNC:-$SY} \
		signal-fps-measurements=true fps-update-interval=1000 >$LOG 2>&1 &
	G=$!
	sleep 1
	[ $SH = ivi ] && export QT_IVI_SURFACE_ID=2000 QT_IVI_GEOMETRY=${QT_IVI_GEOMETRY:-$MODE}
	QT_QPA_PLATFORM=etnaviv2d:plane=wayland QT_ETNA2D_FMT=${QT_ETNA2D_FMT:-$F} QT2D_FPS=${QT2D_FPS:-$UF} \
		cockpit --clip $C --cond $SH-shell --fpslog $LOG ${AUTO:+--auto $AUTO} "$@" &
	Q=$!
	wait $G
	kill $Q 2>/dev/null
else
	P=${POPUP:-$MODE}
	if [ ! -f "$A/videos/clip_${P}_1.h264" ]; then
		[ -n "$POPUP" ] && { echo "missing $A/videos/clip_${P}_1.h264"; exit 1; }
		F1=$(ls "$A"/videos/clip_*_1.h264 2>/dev/null | head -n 1)
		[ -n "$F1" ] || { echo "no clip_*_1.h264 in $A/videos"; exit 1; }
		P=$(basename "$F1" _1.h264); P=${P#clip_}
	fi
	start_weston ivi
	QT_QPA_PLATFORM=etnaviv2d:plane=wayland QT_IVI_SURFACE_ID=1000 QT_IVI_GEOMETRY=${QT_IVI_GEOMETRY:-$MODE} \
		QT_ETNA2D_FMT=${QT_ETNA2D_FMT:-rgb565} QT2D_FPS=${QT2D_FPS:-30} \
		dashboard --clips $A/videos/clip_${P}_1.h264,$A/videos/clip_${P}_2.h264,$A/videos/clip_${P}_3.h264 \
		--thumbs $A/thumbs --cond ivi-shell "$@"
fi
